def choose_move(observation):
    sx, sy = observation.get("self_position", (0, 0))
    ox, oy = observation.get("opponent_position", (0, 0))
    env = observation.get("environment_name", "resource_collection")
    grid_width = observation.get("grid_width", 10)
    grid_height = observation.get("grid_height", 10)

    # Helper function for decision making towards a target
    def move_towards(target_x, target_y):
        dx = 0 if target_x == sx else (1 if target_x > sx else -1)
        dy = 0 if target_y == sy else (1 if target_y > sy else -1)
        return [dx, dy]

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return move_towards(ox, oy)
        # For evader, move away from opponent
        dx = 0
        dy = 0
        if ox == sx:
            dx = 1 if ox < grid_width - 1 else -1
        else:
            dx = -1 if ox > sx else 1
        if oy == sy:
            dy = 1 if oy < grid_height - 1 else -1
        else:
            dy = -1 if oy > sy else 1
        return [dx, dy]

    if env == "territory_control":
        targets = (observation.get("unclaimed_cells") or
                   observation.get("opponent_territory") or [])
        if not targets:
            return [0, 0]
        # Move towards the closest target
        best = min(targets, key=lambda c: abs(c[0] - sx) + abs(c[1] - sy))
        return move_towards(best[0], best[1])

    resources = observation.get("resources") or []
    if resources:
        best_resource = min(resources, key=lambda c: abs(c[0] - sx) + abs(c[1] - sy))
        return move_towards(best_resource[0], best_resource[1])
    else:
        # No resources: move randomly defensively
        dx = 0
        dy = 0
        if ox != sx:
            dx = 1 if ox > sx else -1
        else:
            # Randomly choose to move left or right
            dx = 1
        if oy != sy:
            dy = 1 if oy > sy else -1
        else:
            # Randomly choose to move up or down
            dy = 1
        return [dx, dy]

